function getCurrentWeekDaysArray(date) {
    const millisecondsOfDay = 24 * 60 * 60 * 1000
    let dayOfWeek = date.getDay()
    if (dayOfWeek === 0) dayOfWeek = 7
    const startDate = new Date(date.getTime() - (dayOfWeek - 1) * millisecondsOfDay)
    const endDate = new Date(date.getTime() + (1 - dayOfWeek) * millisecondsOfDay)
    let arr = []
    arr.push(startDate.Format('yyyy-MM-dd'))
    for (var i = 1; i <= 6; i++) {
        let dt = new Date(date.getTime() - (dayOfWeek - 1 - i) * millisecondsOfDay).Format('yyyy-MM-dd')
        arr.push(dt)
    }
    console.log(startDate)
    console.log(endDate)
    return arr
}
