/*
 * 根据时间下拉项和班次下拉项，请求查询时间范围
 */
this.onChangeTime = async () => {
    let date = this.$component('#select1').value;
    let range = this.$model('selrange');
    // 封装starttime，endtime参数
    if (date === 'day') {
        if (range === '') {
            let now = this.dateFormat(new Date(), 'yyyy-MM-dd');
            this.$model('starttime', now + " 00:00:00");
            this.$model('endtime', now + " 23:59:59");
        } else {
            await this.$queryData('SQL21280647', {
                'type': 'day',
                'range': range
            }, 'list').then(res => {
                if (res.data.data && res.data.data.length > 0) {
                    this.$model('starttime', res.data.data[0].start_time);
                    this.$model('endtime', res.data.data[0].end_time);
                }
            })
        }
    } else if (date === 'week') {
        if (range === '') {
            let now = new Date();
            let day = now.getDay();
            let before;
            let after;
            if (day === 0) {
                // 周日获取的day为0
                before = this.getDate(now, -6);
                after = this.getDate(now, 0);
            } else {
                before = this.getDate(now, 1 - day);
                after = this.getDate(now, 7 - day);
            }
            this.$model('starttime', before + " 00:00:00");
            this.$model('endtime', after + " 23:59:59");
        } else {
            await this.$queryData('SQL21280647', {
                'type': 'week',
                'range': range
            }, 'list').then(res => {
                if (res.data.data && res.data.data.length > 0) {
                    this.$model('starttime', res.data.data[0].start_time);
                    this.$model('endtime', res.data.data[0].end_time);
                }
            })
        }
    } else if (date === 'month') {
        if (range === '') {
            let year = new Date().getFullYear();
            let month = new Date().getMonth() + 1;
            let now = new Date(year, month, 0);
            let endOfMonth = now.getDate();
            if (month.toString().length === 1) {
                month = '0' + month;
            }
            let prefix = year + '-' + month + '-';
            this.$model('starttime', prefix + "01" + " 00:00:00");
            this.$model('endtime', prefix + endOfMonth + " 23:59:59");
        } else {
            await this.$queryData('SQL21280647', {
                'type': 'month',
                'range': range
            }, 'list').then(res => {
                if (res.data.data && res.data.data.length > 0) {
                    this.$model('starttime', res.data.data[0].start_time);
                    this.$model('endtime', res.data.data[0].end_time);
                }
            })
        }
    }
}

