/*
 * 封装任务量趋势数据请求	
 * type 1:单地图 2:多地图
 */
this.initTaskCountTrend = async () => {
    console.log('1');
    let type = 2;
    let mapCodes = [];
    if (this.$model("mapcode")) {
        let temp = this.$model("mapcode").split(',');
        temp.forEach(function(item) {
            if (item !== 'all') {
                mapCodes.push(item);
            }
        })
    }
    if (mapCodes.length === 1 || Object.keys(maps).length === 1) {
        type = 1;
    }
    let chart = this.$component('#taskcounttrend');
    let options = chart.chartOptions;
    options.series[0].data = [];
    options.series[1].data = [];
    if (type === 1) {
        // 双折线
        let xData = this.packSingleMapXDataForTrend();
        let sbtype = 1; // 请求时间
        if (this.$component('#select1').value === 'week' ||
            this.$component('#select1').value === 'month') {
            // 请求天
            sbtype = 2;
        }
        let param = {
            sbtype: sbtype,
            starttime: this.$model('starttime'),
            endtime: this.$model('endtime'),
            mapcode: mapCodes.join(),
            range: this.$model('selrange')
        }
        let result = await this.$queryData('SQL21050111', param, 'list');
        let data = result.data.data;
        if (data && data.length > 0) {
            let xMap = {};
            let max = 0;
            for (let i in data) {
                if (this.$component('#select1').value === 'day') {
                    // 截取时间
                    let subTime = data[i].sbtime.substr(11, 2);
                    if (subTime.indexOf('0') === 0) {
                        subTime = subTime.replace('0', '');
                    }
                    xMap[subTime] = data[i].counts;
                } else {
                    xMap[data[i].sbtime] = data[i].counts;
                }
                max = data[i].counts > max ? data[i].counts : max;
            }
            let seriesData = [];
            let before = true; // brefore之前无数据展示0， 之后展示''
            for (let i in xData) {
                if (xMap[xData[i]]) {
                    seriesData.push(xMap[xData[i]]);
                } else {
                    if (before) {
                        seriesData.push(0);
                    } else {
                        seriesData.push('');
                    }
                }
                if (before) {
                    if (this.$component('#select1').value === 'day') {
                        if (new Date().getHours() === parseInt(xData[i])) {
                            before = false;
                        }
                    } else {
                        if (this.dateFormat(new Date(), 'yyyy-MM-dd') === xData[i]) {
                            before = false;
                        }
                    }
                }
            }
            options.series[0].type = 'line';
            options.series[0].data = seriesData;
            options.series[0].label['formatter'] = function(data) {
                if (data.dataIndex % 2 === 1 || data.value.toString().length > 3) {
                    let dt = parseFloat(seriesData[data.dataIndex])
                    let dtPre = parseFloat(seriesData[data.dataIndex - 1])
                    if (dt !== dtPre) {
                        if (data.value.toString().length > 3) {
                            if (data.dataIndex % 3 === 0) {
                                return data.value;
                            } else {
                                return '';
                            }
                        } else {
                            return data.value
                        }
                    } else {
                        return ''
                    }
                } else {
                    return data.value
                }
            };
            options.series[0].color.x2 = 1;
            options.series[0].color.y2 = 0;
            max = max > 10 ? (Math.floor(max / 10) + 1) * 10 : max;
            //options.yAxis[0].max = max;
            // 实时设备数
            let result2 = await this.$queryData('SQL15555517', param, 'list');
            let data2 = result2.data.data;
            let amrMap = {};
            if (data2 && data2.length > 0) {
                for (let i in data2) {
                    if (this.$component('#select1').value === 'day') {
                        let subTime = data2[i].sbtime.substr(11, 2);
                        if (subTime.indexOf('0') === 0) {
                            subTime = subTime.replace('0', '');
                        }
                        amrMap[subTime] = data2[i].amr_count;
                    } else {
                        amrMap[data2[i].sbtime] = data2[i].amr_count;
                    }
                }
            }
            let seriesData2 = [];
            let max2 = 0;
            for (let i in xData) {
                if (seriesData[i] !== '' && amrMap[xData[i]] && 0 !== amrMap[xData[i]]) {
                    let c = Math.round(seriesData[i] / amrMap[xData[i]]);
                    if (seriesData[i] !== 0 && c === 0) {
                        seriesData2.push(1);
                    } else {
                        seriesData2.push(c);
                    }
                } else {
                    seriesData2.push(seriesData[i]);
                }
                max2 = seriesData2[i] > max2 ? seriesData2[i] : max2;
            }
            options.series[1].data = seriesData2;
            max2 = max2 > 10 ? (Math.floor(max2 / 10) + 1) * 10 : max2;
            //options.yAxis[1].max = max2;
        } else {
            options.series[0].data = [];
            options.series[1].data = [];
        }
        console.log(xData);
        if (this.$component('#select1').value === 'week') {
            //xData = ['周一', '周二', '周三', '周四', '周五', '周六', '周日']
            xData = [this.$text('$mon'), this.$text('$tue'), this.$text('$wed'), this.$text('$thu'), this.$text('$fri'), this.$text('$sat'), this.$text('$sun')]
        } else if (this.$component('#select1').value === 'month') {
            for (let i in xData) {
                xData[i] = xData[i].substr(8, 2);
                if (xData[i].indexOf('0') === 0) {
                    xData[i] = xData[i].replace('0', '');
                }
            }
        }
        options.xAxis[0].data = xData;
        options.series[1].zlevel = 0;
        this.taskCountTrendDataZoom(0, chart, options);
    } else {
        // 折柱混合
        let param = {
            starttime: this.$model('starttime'),
            endtime: this.$model('endtime'),
            range: this.$model('selrange')
        }
        if (mapCodes.length > 0) {
            param['mapcodes'] = mapCodes.join(',')
        }
        // 任务结果
        let result = await this.$queryData('SQL11373715', param, 'list');
        let data = result.data.data;
        if (data && data.length > 0) {
            let xData = [];
            let seriesData = [];
            let max = 0;
            for (let i in data) {
                if (maps[data[i].mapcode]) {
                    xData.push(maps[data[i].mapcode]);
                } else {
                    xData.push(data[i].mapcode);
                }
                seriesData.push(data[i].counts);
                max = data[i].counts > max ? data[i].counts : max;
            }
            options.series[0].type = 'bar';
            options.series[0].data = seriesData;
            options.series[0].label['formatter'] = function(data) {
                return data.value;
            };
            options.series[0].color.x2 = 0;
            options.series[0].color.y2 = 1;
            options.xAxis[0].data = xData;
            max = max > 10 ? (Math.floor(max / 10) + 1) * 10 : max;
            //options.yAxis[0].max = max;
            //options.yAxis[1].max = max;
            // 实时设备数
            let result2 = await this.$queryData('SQL15562118', param, 'list');
            let data2 = result2.data.data;
            let amrMap = {};
            if (data2 && data2.length > 0) {
                for (let i in data2) {
                    amrMap[data2[i].map_code] = data2[i].amr_count;
                }
            }
            let seriesData2 = [];
            for (let i in data) {
                if (amrMap[data[i].mapcode] && 0 !== amrMap[data[i].mapcode]) {
                    let c = Math.round(seriesData[i] / amrMap[data[i].mapcode]);
                    if (seriesData[i] !== 0 && c === 0) {
                        seriesData2.push(1);
                    } else {
                        seriesData2.push(c);
                    }
                } else {
                    seriesData2.push(seriesData[i]);
                }
            }
            options.series[1].data = seriesData2;
        } else {
            options.xAxis[0].data = [];
            options.series[0].data = [];
            options.series[1].data = [];
        }
        options.series[1].zlevel = 2;
        this.taskCountTrendDataZoom(options.xAxis[0].data.length, chart, options);
    }
    let rotate = 0;
    if (options.xAxis[0].data.length > 0) {
        if (options.xAxis[0].data[0].length >= 3) {
            rotate = 30;
        }
    }
    options.xAxis[0].axisLabel.rotate = rotate;
    this.$nextTick(() => {
        chart.refreshOption(options);
    })
    console.log(options)
}
