        taskCountTrendDataZoomTimer = setInterval(() => {
            option.dataZoom.start = taskCountTrendDataZoomStart;
            option.dataZoom.end = taskCountTrendDataZoomEnd;
            let interval = Math.round(100 / length);
            taskCountTrendDataZoomStart += interval;
            taskCountTrendDataZoomEnd += interval;
            if (taskCountTrendDataZoomEnd >= 100) {
                taskCountTrendDataZoomStart = 0;
                taskCountTrendDataZoomEnd = Math.round(100 * (5 / length));
            }
            console.log('datazoom');
            this.$nextTick(() => {
                chart.refreshOption(option);
            })
        }, 5000);
    }
}
/*
 * 封装单地图x轴
 */
this.packSingleMapXDataForTrend = () => {
    let xData = [];
    if (this.$component('#select1').value === 'day') {
        // 当日时间趋势
        let time1 = parseInt(this.$model('starttime').substr(11, 2));
        let time2 = parseInt(this.$model('endtime').substr(11, 2));
        if (time1 < time2) {
            // 正点班次
            xData.push(time1.toString());
            for (let i = 1; i <= time2 - time1; i++) {
                let temp = parseInt(time1) + i;
                xData.push(temp.toString());
            }
        } else {
            // 夜班跨天班次
            xData.push(time1.toString());
            let temp = new Date();
            temp.setHours(time1);
            for (let i = 1; i <= 24 - time1; i++) {
                temp.setHours(temp.getHours() + 1);
                let temp2 = temp.getHours();
                xData.push(temp2.toString());
            }
            for (let i = 1; i <= time2 - 0; i++) {
                temp.setHours(temp.getHours() + 1);
                let temp2 = temp.getHours();
                xData.push(temp2.toString());
            }
        }
    } else if (this.$component('#select1').value === 'week') {
        // 显示整周
        let day1 = this.$model('starttime').substr(0, 10);
        xData.push(day1);
        let firstDay = new Date(day1);
        for (let i = 1; i < 7; i++) {
            xData.push(this.getDate(firstDay, i));
        }
    } else if (this.$component('#select1').value === 'month') {
        // 显示整月
        let day1 = this.$model('starttime').substr(0, 10);
        xData.push(day1);
        let firstDay = new Date(day1);
        let year = new Date().getFullYear();
        let month = new Date().getMonth() + 1;
        let now = new Date(year, month, 0);
        let endOfMonth = now.getDate();
        for (let i = 1; i < endOfMonth; i++) {
            xData.push(this.getDate(firstDay, i));
        }
    }
    return xData;
}

/*
 * 格式化时间
 */
this.dateFormat = (date, fmt) => {
    var o = {
        "M+": date.getMonth() + 1, //月份
        "d+": date.getDate(), //日
        "H+": date.getHours(), //小时
        "m+": date.getMinutes(), //分
        "s+": date.getSeconds(), //秒
        "q+": Math.floor((date.getMonth() + 3) / 3), //季度
        "S": date.getMilliseconds() //毫秒
    };
    if (/(y+)/.test(fmt)) fmt = fmt.replace(RegExp.$1, (date.getFullYear() + "").substr(4 - RegExp.$1.length));
    for (var k in o)
        if (new RegExp("(" + k + ")").test(fmt)) fmt = fmt.replace(RegExp.$1, (RegExp.$1.length == 1) ? (o[k]) : (("00" + o[k]).substr(("" + o[k]).length)));
    return fmt;
}

/*
 * 计算时间
 */
this.getDate = (date, day) => {
    var dd = new Date(date);
    dd.setDate(dd.getDate() + day);
    var y = dd.getFullYear();
    var m = dd.getMonth() + 1 < 10 ? "0" + (dd.getMonth() + 1) : dd.getMonth() + 1;
    var d = dd.getDate() < 10 ? "0" + dd.getDate() : dd.getDate();
    return y + "-" + m + "-" + d;
}

